head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > oncelldatachange]<br/>DataList 모듈에서 특정 Cell 의 값이 변경된 후 발생합니다.",
    "validation" : [
        "useNull=false 이면 null 값이 ''(Empty String)으로 처리됩니다.",
        "'삽입', '제거' 와 같이 DataList 모듈의 Row 변경이 발생하는 경우 oncelldatachange 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        useNull: false,
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩        
    target1.bind("oncelldatachange", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncelldatachange=====");
        wf_body_bottom.getObj("scwin").setReturnValue("info: " + info);   
        wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue: " + info.oldValue);   
        wf_body_bottom.getObj("scwin").setReturnValue("info.newValue: " + info.newValue);   
        wf_body_bottom.getObj("scwin").setReturnValue("info.realRowIndex: " + info.realRowIndex);   
        wf_body_bottom.getObj("scwin").setReturnValue("info.rowIndex: " + info.rowIndex);   
        wf_body_bottom.getObj("scwin").setReturnValue("info.colID: " + info.colID);   
    });     

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(0, 0, null);
};



scwin.btn_insertJSON_onclick = function (e) {
	target1.insertJSON(0, [
        {col1:"insert1",col2:"insert2",col3:"insert3",col4:"insert4"},
        {col1:"insert5",col2:"insert6",col3:"insert7",col4:"insert8"}
    ]);
};



scwin.btn_removeRows_onclick = function (e) {
	target1.removeRows([0, 1]);
};
